// JATAYU 2.0 Audio Alert Helper
function playDemoEarlyWarningTone(muted) {
  if (muted || typeof window === 'undefined') return;
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(580, now);
    osc.frequency.setValueAtTime(780, now + 0.25);
    osc.frequency.setValueAtTime(580, now + 0.50);
    osc.frequency.setValueAtTime(780, now + 0.75);
    gain.gain.setValueAtTime(0.0, now);
    gain.gain.linearRampToValueAtTime(0.12, now + 0.05);
    gain.gain.setValueAtTime(0.12, now + 0.85);
    gain.gain.linearRampToValueAtTime(0.0, now + 1.10);
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.start(now);
    osc.stop(now + 1.15);
  } catch (e) {
    console.warn('Audio alert unavailable:', e);
  }
}

// JATAYU 2.0 Server-Side Telegram Dispatch & Connection Helpers
async function dispatchTelegramAlert(payload) {
  try {
    const res = await fetch('/api/telegram-alert', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    return data;
  } catch (err) {
    console.warn('[JATAYU] Telegram dispatch failed:', err);
    return { ok: false, error: err?.message || 'Network error reaching Telegram API gateway' };
  }
}

async function testTelegramConnection() {
  try {
    const res = await fetch('/api/telegram-test', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' }
    });
    const data = await res.json();
    return data;
  } catch (err) {
    console.warn('[JATAYU] Telegram test failed:', err);
    return { ok: false, error: err?.message || 'Network error reaching Telegram test gateway' };
  }
}

